{"version":"AzureDataExplorerQuery/1.0","queryText":"let Current = (
// Copyright (c) Microsoft Corporation.
// Licensed under the MIT License.
//
// NAME: App Service quota usage
// DESCRIPTION: Rehydrates the latest App Service quota usage records for each subscription and region.
// CATEGORY: Governance
// FEATURE: Quota
// REGION: All
// TECH: KQL
//
// RESOURCE TYPES: Microsoft.Web/locations/usages
//
// SOURCE: Quota()
//

Quota()
| where x_SourceType =~ 'AppServiceUsage'
| where ResourceType =~ 'Microsoft.Web/locations/usages'
| where isnotempty(ResourceName)
| summarize arg_max(x_IngestionTime, *) by ResourceId
| project
    ProviderName,
    ResourceId,
    ResourceName,
    ResourceType,
    SubAccountId,
    displayName,
    location,
    currentValue,
    limit,
    unit,
    x_QuotaDetails,
    x_SourceType,
    x_SourceVersion,
    x_IngestionTime
| order by SubAccountId asc, location asc, ResourceName asc
);
Current
| extend CurrentValue=todouble(currentValue), LimitValue=todouble(limit)
| summarize
    Current=sum(CurrentValue),
    UsableLimit=sumif(LimitValue, LimitValue > 0),
    QuotaMetrics=dcount(displayName),
    Subscriptions=dcount(SubAccountId),
    Observations=count(),
    LatestObservation=max(x_IngestionTime)
    by Region=location, Unit=unit
| extend
    Headroom=UsableLimit - Current,
    UtilizationPercent=iff(UsableLimit > 0, round(100.0 * Current / UsableLimit, 1), real(null))
| order by UtilizationPercent desc nulls last","clusterName":"{HubClusterName}","databaseName":"{HubDatabase}"}

